{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Early warning signs include evidence of health, safety, or behavioral issues, such as substance abuse, mental health issues, suicidal ideation, self-harm, threats of violence, or being a victim or perpetrator of harassment, intimidation, bullying, or cyberbullying.",
      "rationale": "Conveys the definition's scope and nonexclusive examples, including both victims and perpetrators."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "This bill proposes the \"Early Behavioral Intervention and Reporting Act,\" which would require local education agencies (LEAs) and public charter schools to use a computer-based system to track \"early warning signs\" in students.",
      "rationale": "Conveys the required computer-based system for both entities; the following paragraph explains teacher and staff entry, and the summary separately describes the existing-system exception."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Under this proposal, LEAs and public charter schools must train teachers and staff to identify these signs and enter them into the system.",
      "rationale": "Conveys both required training subjects and the responsible entities. The existing-system exception is addressed separately."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The system must align with existing school safety and discipline policies",
      "rationale": "Conveys safety and discipline alignment but does not identify the required harassment, intimidation, bullying, and cyberbullying policy or clearly convey alignment with the School Discipline Act and each SAVE Act safety plan."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "maintain a database of the entries",
      "rationale": "In the context of teacher and staff entry into the system, this conveys a database that receives and retains early-warning-sign data."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "immediately notify the LEA's threat assessment team or a designated charter school employee",
      "rationale": "Conveys immediate notification to the appropriate recipients in the context of entering warning signs into the system."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "Personnel receiving these notifications must review the data to determine if further action is needed.",
      "rationale": "Conveys review and the further-action determination, but omits the requirement to review all previously received notifications for the same student."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "LEAs and public charter schools would be required to submit an annual report to the department of education. This report must include the number of warning signs recorded",
      "rationale": "Conveys the reporting entities, recipient, frequency, and total count, but omits that the data must cover the immediately preceding school year."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "data on which staff members entered the signs",
      "rationale": "Conveys information about who entered signs, but not counts separated by teacher versus staff or the required breakdowns by teaching grade and subject and staff position, assignment, and duties."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "the number of students with multiple warning signs",
      "rationale": "Conveys the number of students with multiple entries but omits the number of entries for each such student."
    },
    {
      "proposition_id": "P11",
      "status": "partial",
      "summary_quote": "general descriptions of the signs and the actions taken. To protect student privacy, these reports must comply with the Family Educational Rights and Privacy Act (FERPA) and other privacy laws, and must not contain information that could identify specific students.",
      "rationale": "Conveys descriptions of signs and responses and the identification prohibition, but does not specify that actions must be described in response to each entered sign."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "must not contain information that could identify specific students",
      "rationale": "Conveys the report-wide prohibition on information allowing student identification."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "these reports must comply with the Family Educational Rights and Privacy Act (FERPA) and other privacy laws",
      "rationale": "Conveys compliance with FERPA and other applicable privacy laws; the omitted statutory names and citations do not change that obligation."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "The commissioner of education may withhold state funds from any LEA or public charter school that fails to comply with these requirements.",
      "rationale": "Conveys discretionary withholding for noncompliance, but omits the commissioner's authority to determine the amount and the limit that withholding lasts until compliance."
    },
    {
      "proposition_id": "P15",
      "status": "partial",
      "summary_quote": "These rules would not apply to schools that already maintained a system for documenting early warning signs before July 1, 2026, as long as they continue to use it.",
      "rationale": "Conveys the prior-system cutoff and continued-use condition, but incorrectly suggests exemption from all rules rather than only subsections (c)-(e). It does not preserve reporting obligations or expressly require continuous maintenance."
    },
    {
      "proposition_id": "P16",
      "status": "full",
      "summary_quote": "The act would take effect on July 1, 2026.",
      "rationale": "States the effective date accurately."
    }
  ]
}
